export { includesValue, itemView, rootView, toggleValue } from "../accordion";
export type {
  AccordionStyle,
  ItemViewConfig,
  RootViewConfig,
} from "../accordion";

export {
  shadcnAccordionHeaderClassName,
  shadcnAccordionIconClassName,
  shadcnAccordionItemClassName,
  shadcnAccordionPanelClassName,
  shadcnAccordionRootClassName,
  shadcnAccordionTriggerClassName,
} from "./view";

export {
  accordionHeaderClassName as shadcnAccordionHeaderClassName,
  accordionIconClassName as shadcnAccordionIconClassName,
  accordionItemClassName as shadcnAccordionItemClassName,
  accordionPanelClassName as shadcnAccordionPanelClassName,
  accordionRootClassName as shadcnAccordionRootClassName,
  accordionTriggerClassName as shadcnAccordionTriggerClassName,
} from "../accordion/view";

import { describe, expect, test } from "vitest";

import * as Accordion from "./index";

describe("shadcn Accordion registry view", () => {
  test("reuses the Foldkit Accordion view contract", () => {
    expect(Accordion.rootView).toBeTypeOf("function");
    expect(Accordion.itemView).toBeTypeOf("function");
    expect(Accordion.toggleValue(["one"], "one")).toEqual([]);
    expect(Accordion.shadcnAccordionTriggerClassName).toContain("font-medium");
  });
});
